        self.task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "Challenge", "StartVerification", "VerifySnapshot", "ExecuteRelay", "ReconcileClaim"]);

        self.task_store.lock().unwrap().add_task(Task {
            epoch,
            execute_after: block_ts,
            kind: TaskKind::WithdrawDeposit,
        });
    }

